#include <stdio.h>
#include <string.h>

#define MOD 1000000007
#define MAXN 3005

int n, q;
int a[MAXN];
long long prob[MAXN][MAXN]; // prob[i][j] = probability that A_i > A_j (i != j)
long long inv2 = (MOD + 1) / 2; // modular inverse of 2

long long mod_pow(long long base, long long exp) {
    long long res = 1;
    while (exp) {
        if (exp & 1) res = res * base % MOD;
        base = base * base % MOD;
        exp >>= 1;
    }
    return res;
}

int main() {
    scanf("%d %d", &n, &q);
    for (int i = 1; i <= n; i++) {
        scanf("%d", &a[i]);
    }

    // Initialize probabilities based on initial values
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            if (i == j) continue;
            if (a[i] > a[j]) prob[i][j] = 1;
            else prob[i][j] = 0;
        }
    }

    for (int op = 0; op < q; op++) {
        int x, y;
        scanf("%d %d", &x, &y);
        if (x == y) continue;

        // Update probabilities for all k != x,y
        for (int k = 1; k <= n; k++) {
            if (k == x || k == y) continue;
            long long pxk = prob[x][k];
            long long pyk = prob[y][k];
            long long pkx = prob[k][x];
            long long pky = prob[k][y];

            // After swap with prob 1/2, new values:
            // With prob 1/2: no swap -> keep pxk, pyk
            // With prob 1/2: swap -> new prob[x][k] = pyk, new prob[y][k] = pxk
            prob[x][k] = (pxk + pyk) * inv2 % MOD;
            prob[y][k] = (pxk + pyk) * inv2 % MOD;

            prob[k][x] = (pkx + pky) * inv2 % MOD;
            prob[k][y] = (pkx + pky) * inv2 % MOD;
        }
        // For pair (x,y) itself:
        long long pxy = prob[x][y];
        long long pyx = prob[y][x];
        // If swap: prob[x][y] becomes pyx, prob[y][x] becomes pxy
        prob[x][y] = (pxy + pyx) * inv2 % MOD;
        prob[y][x] = (pxy + pyx) * inv2 % MOD;
    }

    long long total = 0;
    for (int i = 1; i <= n; i++) {
        for (int j = i+1; j <= n; j++) {
            total = (total + prob[i][j]) % MOD;
        }
    }

    long long pow2q = mod_pow(2, q);
    long long ans = total * pow2q % MOD;
    printf("%lld\n", ans);
    return 0;
}

