    // Too much memory for large N. Let's assume N<=2000, Q<=2000
    // Use per-pair tracking
    long long ans=0;
    long long pw=1; for(int i=0;i<Q;i++) pw=pw*2%MOD;
    // For each pair p<q
    for(int p=1;p<=N;p++) for(int q=p+1;q<=N;q++){
        // track dist[sp][sq] = number of ways
        static long long dist[2001][2001];
        memset(dist,0,sizeof(dist));
        dist[p][q]=1;
        for(int k=0;k<Q;k++){
            int x=X[k],y=Y[k];
            // swap: new_dist[sp'][sq'] += dist[sp][sq] where sp'=swap_pos(sp), sq'=swap_pos(sq)
            // no-swap: new_dist[sp][sq] += dist[sp][sq]
            // Combined: dist[sp][sq]*2 except when x,y involved
            // Actually just: for each (sp,sq), two choices
            static long long nd[2001][2001];
            memset(nd,0,sizeof(nd));
            for(int sp=1;sp<=N;sp++) for(int sq=1;sq<=N;sq++){
                if(!dist[sp][sq]) continue;
                long long v=dist[sp][sq];
