                // swap: position x and y exchange their sources
                int sp2=(sp==x)?y:(sp==y)?x:sp;
                int sq2=(sq==x)?y:(sq==y)?x:sq;
                nd[sp2][sq2]=(nd[sp2][sq2]+v)%MOD;
            }
            memcpy(dist,nd,sizeof(nd));
        }
        // count
        for(int sp=1;sp<=N;sp++) for(int sq=1;sq<=N;sq++){
