#define MOD 1000000007LL

typedef long long ll;

static ll mod_pow(ll a, ll e) {
    ll r = 1 % MOD;
    while (e > 0) {
        if (e & 1) r = r * a % MOD;
        a = a * a % MOD;
        e >>= 1;
    }
    return r;
}

int main(void) {
    int N, Q;
    if (scanf("%d %d", &N, &Q) != 2) return 0;

    int *A = (int*)malloc((N + 1) * sizeof(int));
    for (int i = 1; i <= N; i++) scanf("%d", &A[i]);

    int *X = (int*)malloc(Q * sizeof(int));
    int *Y = (int*)malloc(Q * sizeof(int));
    for (int i = 0; i < Q; i++) scanf("%d %d", &X[i], &Y[i]);

    /* p[i][j]: probability numerator over denominator 2^t that value at i > value at j
       after processed operations so far, for i<j.
       We store values modulo MOD. Initially 0 or 1.
    */
    ll **p = (ll**)malloc((N + 1) * sizeof(ll*));
    for (int i = 0; i <= N; i++) {
        p[i] = (ll*)calloc(N + 1, sizeof(ll));
    }

    for (int i = 1; i <= N; i++) {
        for (int j = i + 1; j <= N; j++) {
            p[i][j] = (A[i] > A[j]) ? 1 : 0;
        }
    }

    ll inv2 = (MOD + 1) / 2;

    for (int qi = 0; qi < Q; qi++) {
        int x = X[qi], y = Y[qi];
        if (x == y) continue;
        if (x > y) {
            int tmp = x; x = y; y = tmp;
        }

        ll old_xy = p[x][y];
        p[x][y] = (1 - old_xy + MOD) % MOD;

        for (int k = 1; k < x; k++) {
            ll a = p[k][x];
            ll b = p[k][y];
            ll v = (a + b) * inv2 % MOD;
            p[k][x] = v;
            p[k][y] = v;
        }

        for (int k = x + 1; k < y; k++) {
            ll a = p[x][k];
            ll b = p[k][y]; /* note: p[k][y] means A_k > A_y */
            ll v1 = (a + (1 - b + MOD) % MOD) * inv2 % MOD; /* P(new x > k) */
            ll v2 = ((1 - a + MOD) % MOD + b) * inv2 % MOD; /* P(k > new y) */
            p[x][k] = v1;
            p[k][y] = v2;
        }

        for (int k = y + 1; k <= N; k++) {
            ll a = p[x][k];
            ll b = p[y][k];
            ll v = (a + b) * inv2 % MOD;
            p[x][k] = v;
            p[y][k] = v;
        }
    }

    ll ans = 0;
    for (int i = 1; i <= N; i++) {
        for (int j = i + 1; j <= N; j++) {
            ans += p[i][j];
            if (ans >= MOD) ans -= MOD;
        }
    }

    ans = ans * mod_pow(2, Q) % MOD;
    printf("%lld\n", ans);

    for (int i = 0; i <= N; i++) free(p[i]);
    free(p);
    free(A);
    free(X);
    free(Y);
    return 0;
}

