        int x, y;
        cin >> x >> y;
        x--; y--;
        if (x == y) continue;
        if (x > y) swap(x, y);

        // Update probabilities for all pairs involving x or y
        for (int k = 0; k < N; k++) {
            if (k == x || k == y) continue;
            // Pairs (x,k) and (k,x) are affected
            if (k < x) {
                // pair (k,x)
                int p_kx = prob[k][x];
                int p_ky = prob[k][y];
                // After swap or not, new prob is average of two cases
                prob[k][x] = (int64)(p_kx + p_ky) * inv2 % MOD;
                prob[k][y] = (int64)(p_kx + p_ky) * inv2 % MOD;
            } else if (k > x && k < y) {
                // pair (x,k) and (k,y)
                int p_xk = prob[x][k];
                int p_ky = prob[k][y];
                prob[x][k] = (int64)(p_xk + (1 - p_ky + MOD)) * inv2 % MOD;
                prob[k][y] = (int64)((1 - p_xk + MOD) + p_ky) * inv2 % MOD;
            } else if (k > y) {
                // pair (x,k) and (y,k)
                int p_xk = prob[x][k];
                int p_yk = prob[y][k];
                prob[x][k] = (int64)(p_xk + p_yk) * inv2 % MOD;
                prob[y][k] = (int64)(p_xk + p_yk) * inv2 % MOD;
            }
        }
        // Also update (x,y) itself
        prob[x][y] = (int64)(prob[x][y] + (1 - prob[x][y] + MOD)) * inv2 % MOD;
    }

    int total = 0;
    for (int i = 0; i < N; i++) {
        for (int j = i+1; j < N; j++) {
            total = (total + prob[i][j]) % MOD;
        }
    }
    // Multiply by 2^Q
    total = (int64)total * modpow(2, Q) % MOD;
    cout << total << "\n";

    return 0;
