using namespace std;

static const long long MOD = 1000000007LL;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, Q;
    cin >> N >> Q;
    vector<long long> A(N + 1);
    for (int i = 1; i <= N; i++) cin >> A[i];

    vector<int> X(Q + 1), Y(Q + 1);
    for (int i = 1; i <= Q; i++) cin >> X[i] >> Y[i];

    // dp[i][j]:
    // probability * 2^processed_ops that final value at position i
    // is greater than final value at position j, after processed operations.
    //
    // More precisely, we maintain values modulo MOD, starting from 0/1.
    // Transition for operation (x,y):
    // For any k != x,y:
    //   dp[x][k], dp[y][k] become average of previous two
    //   dp[k][x], dp[k][y] become average of previous two
    // And dp[x][y], dp[y][x] become average too.
    //
    // To avoid divisions during updates, we store actual probabilities modulo MOD
    // and multiply final sum by 2^Q.
    vector<vector<long long>> dp(N + 1, vector<long long>(N + 1, 0));

    for (int i = 1; i <= N; i++) {
        for (int j = i + 1; j <= N; j++) {
            if (A[i] > A[j]) dp[i][j] = 1;
            else dp[i][j] = 0;
            dp[j][i] = (1 - dp[i][j] + MOD) % MOD; // since all A are distinct? No.
        }
    }

    // Fix equal values properly:
    // If A[i] == A[j], both directions should be 0.
    for (int i = 1; i <= N; i++) {
        for (int j = i + 1; j <= N; j++) {
            if (A[i] == A[j]) {
                dp[i][j] = 0;
                dp[j][i] = 0;
            } else {
                dp[i][j] = (A[i] > A[j]) ? 1 : 0;
                dp[j][i] = (A[j] > A[i]) ? 1 : 0;
            }
        }
    }

    long long inv2 = (MOD + 1) / 2;

    for (int qi = 1; qi <= Q; qi++) {
        int x = X[qi], y = Y[qi];

        for (int k = 1; k <= N; k++) {
            if (k == x || k == y) continue;

            long long v1 = (dp[x][k] + dp[y][k]) * inv2 % MOD;
            long long v2 = (dp[k][x] + dp[k][y]) * inv2 % MOD;

            dp[x][k] = dp[y][k] = v1;
            dp[k][x] = dp[k][y] = v2;
        }

        long long v = (dp[x][y] + dp[y][x]) * inv2 % MOD;
        dp[x][y] = dp[y][x] = v;
    }

    long long sumProb = 0;
    for (int i = 1; i <= N; i++) {
        for (int j = i + 1; j <= N; j++) {
            sumProb += dp[i][j];
            if (sumProb >= MOD) sumProb -= MOD;
        }
    }

    long long pow2 = 1;
    for (int i = 0; i < Q; i++) pow2 = pow2 * 2 % MOD;

    long long ans = sumProb * pow2 % MOD;
    cout << ans % MOD << '\n';
    return 0;
}

